insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('porridge-banane-amande', 'Porridge crémeux banane et amande', 'Un petit-déjeuner chaud, prêt en 10 minutes.', array['pregnancy','family']::text[], array['breakfast']::text[], array[]::text[], null, null, array['regular']::text[], 1, null, 3, 7, array['gluten','milk','nuts']::text[], array['quick','budget','vegetarian','fiber','calcium','fatigue']::text[], array['Sans lait de vache : boisson à l’avoine enrichie en calcium (pas de boisson au soja pendant la grossesse).','Allergie aux fruits à coque : remplacez la poudre d’amande par des graines de courge moulues.']::text[], 'À préparer au moment ; les flocons secs se conservent fermés dans un placard.', array['Produits laitiers pasteurisés uniquement ; fromages à pâte pressée cuite (emmental, comté, parmesan) sans leur croûte, râpés à la maison : pas de fromage vendu déjà râpé.']::text[], 'Les flocons d’avoine apportent des fibres et des glucides complexes ; le lait apporte du calcium et des protéines.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
