insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'porridge-banane-amande' and owner_id is null), 1, 'Versez les flocons d’avoine et le lait dans une petite casserole.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'porridge-banane-amande' and owner_id is null), 2, 'Faites cuire 5 à 7 minutes à feu doux en remuant, jusqu’à ce que le mélange épaississe.') on conflict do nothing;
