insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('tartines-fromage-frais-kiwi', 'Tartines de pain complet, fromage frais et kiwi', 'Petit-déjeuner frais, sans cuisson.', array['pregnancy']::text[], array['breakfast','snack']::text[], array[]::text[], null, null, array['regular']::text[], 1, null, 5, 2, array['gluten','milk']::text[], array['quick','vegetarian','fiber','calcium']::text[], array['Remplacez le kiwi par une orange en quartiers ou des fraises lavées selon la saison.']::text[], 'À préparer au moment. Fromage frais entamé : au réfrigérateur, à consommer rapidement une fois ouvert.', array['Produits laitiers pasteurisés uniquement ; fromages à pâte pressée cuite (emmental, comté, parmesan) sans leur croûte, râpés à la maison : pas de fromage vendu déjà râpé.','Lavez soigneusement les fruits, les légumes et les herbes, même ceux vendus prêts à consommer (toxoplasmose, listériose).']::text[], 'Le pain complet apporte des fibres ; le kiwi apporte de la vitamine C, qui aide à absorber le fer des aliments végétaux.', 1, array['winter','spring']::text[], 'cold', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
