insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('omelette-epinards-bien-cuite', 'Omelette bien cuite aux épinards', 'Prête en 15 minutes, avec du pain complet.', array['pregnancy','family']::text[], array['breakfast','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 5, 10, array['eggs','milk','gluten']::text[], array['quick','vegetarian','protein','iron','b9']::text[], array['Sans gluten : servez avec des pommes de terre vapeur au lieu du pain.']::text[], 'À manger aussitôt. Ne conservez pas les restes d’œufs plus de 24 h au réfrigérateur.', array['Œufs cuits jusqu’à ce que le blanc et le jaune soient fermes.','Produits laitiers pasteurisés uniquement ; fromages à pâte pressée cuite (emmental, comté, parmesan) sans leur croûte, râpés à la maison : pas de fromage vendu déjà râpé.','Lavez soigneusement les fruits, les légumes et les herbes, même ceux vendus prêts à consommer (toxoplasmose, listériose).']::text[], 'Les œufs apportent des protéines ; les épinards apportent des folates (vitamine B9).', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
