insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('yaourt-compote-avoine-noix', 'Yaourt, compote maison et flocons d’avoine', 'Une collation ou un petit-déjeuner sans cuisson après la compote.', array['pregnancy']::text[], array['breakfast','snack']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 10, 15, array['milk','gluten','nuts']::text[], array['budget','vegetarian','calcium','fiber','make_ahead']::text[], array['La compote se prépare la veille ; elle se garde 3 jours au réfrigérateur dans une boîte fermée.']::text[], 'Compote : 3 jours au réfrigérateur, ou 2 mois au congélateur.', array['Produits laitiers pasteurisés uniquement ; fromages à pâte pressée cuite (emmental, comté, parmesan) sans leur croûte, râpés à la maison : pas de fromage vendu déjà râpé.','Lavez soigneusement les fruits, les légumes et les herbes, même ceux vendus prêts à consommer (toxoplasmose, listériose).']::text[], 'Le yaourt apporte du calcium ; la pomme et l’avoine apportent des fibres ; les noix apportent des acides gras oméga-3 d’origine végétale.', 1, array['autumn','winter']::text[], 'cold', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
