insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('salade-lentilles-carottes-oeuf', 'Salade tiède de lentilles, carottes râpées et œuf dur', 'Un déjeuner complet et économique.', array['pregnancy']::text[], array['lunch']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 15, 25, array['eggs']::text[], array['budget','vegetarian','iron','b9','fiber','protein','make_ahead']::text[], array['Pour gagner du temps : lentilles déjà cuites en bocal, rincées.','Sans œuf : ajoutez 100 g de pois chiches cuits.']::text[], 'Salade sans les œufs : 24 h au réfrigérateur dans une boîte fermée.', array['Œufs cuits jusqu’à ce que le blanc et le jaune soient fermes.','Lavez soigneusement les fruits, les légumes et les herbes, même ceux vendus prêts à consommer (toxoplasmose, listériose).','Réfrigérateur à 4 °C environ ; restes couverts, consommés sous 24 h et réchauffés jusqu’à être bien chauds.']::text[], 'Les lentilles apportent des fibres, des protéines végétales, du fer et des folates (vitamine B9) ; le citron apporte de la vitamine C.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
