insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('boeuf-patate-douce-haricots', 'Bœuf haché bien cuit, purée de patate douce et haricots verts', 'Un déjeuner simple, source de fer.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 10, 20, array['milk']::text[], array['iron','protein','family']::text[], array['Sans viande : remplacez le bœuf par 2 œufs durs ou 200 g de lentilles cuites.']::text[], 'Purée : 48 h au réfrigérateur. Viande hachée cuite : 24 h, réchauffée jusqu’à être bien chaude.', array['Viande cuite à cœur (plus aucune trace rosée au centre) ; lavez-vous les mains, la planche et les ustensiles après avoir touché la viande crue.','Réfrigérateur à 4 °C environ ; restes couverts, consommés sous 24 h et réchauffés jusqu’à être bien chauds.']::text[], 'La viande rouge apporte du fer et des protéines ; la patate douce et les haricots verts apportent des fibres.', 2, array[]::text[], 'hot', '{"baby":"À partir de la diversification : mixez finement une petite part de viande avec la purée, sans sel.","child":"Coupez la viande en petits morceaux."}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
