insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('saumon-four-riz-brocoli', 'Saumon au four, riz complet et brocoli', 'Le poisson gras de la semaine, bien cuit.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 10, 25, array['fish']::text[], array['protein','b9','family']::text[], array['Remplacez le saumon par du maquereau frais (autre poisson gras), lui aussi bien cuit.']::text[], 'Restes de poisson cuit : 24 h au réfrigérateur, à réchauffer à cœur.', array['Poisson cuit à cœur : la chair doit être opaque et se détacher en lamelles.','Pas de saumon fumé ni cru pendant la grossesse.','Réfrigérateur à 4 °C environ ; restes couverts, consommés sous 24 h et réchauffés jusqu’à être bien chauds.']::text[], 'Le saumon est un poisson gras : il apporte des oméga-3 et de la vitamine D ; le brocoli apporte des folates (vitamine B9).', 3, array[]::text[], 'hot', '{"baby":"Poisson sans arêtes, mixé avec le brocoli et un peu de pomme de terre.","child":"Vérifiez qu’il ne reste aucune arête."}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
