insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('maquereau-four-pommes-de-terre', 'Maquereau au four, pommes de terre et salade', 'Un poisson gras économique.', array['pregnancy']::text[], array['dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 10, 25, array['fish']::text[], array['budget','protein']::text[], array['Remplacez le maquereau par des sardines fraîches, elles aussi bien cuites.']::text[], 'À manger aussitôt ; restes de poisson : 24 h au réfrigérateur.', array['Poisson cuit à cœur : la chair doit être opaque et se détacher en lamelles.','Lavez soigneusement les fruits, les légumes et les herbes, même ceux vendus prêts à consommer (toxoplasmose, listériose).','Pas de poisson fumé ni de poisson cru (sushi) pendant la grossesse.']::text[], 'Le maquereau est un poisson gras qui apporte des oméga-3 et de la vitamine D.', 1, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
