insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('riz-saute-oeufs-petits-pois', 'Riz sauté aux œufs bien cuits et petits pois', 'Un repas rapide pour les soirs de fatigue.', array['pregnancy','family']::text[], array['dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 5, 25, array['eggs']::text[], array['quick','budget','vegetarian','protein','fatigue']::text[], array['Ajoutez des restes de poulet cuit, réchauffés à cœur.']::text[], 'Riz cuit : refroidi rapidement, 24 h au réfrigérateur au maximum ; réchauffé une seule fois, bien chaud.', array['Œufs cuits jusqu’à ce que le blanc et le jaune soient fermes.','Réfrigérateur à 4 °C environ ; restes couverts, consommés sous 24 h et réchauffés jusqu’à être bien chauds.']::text[], 'Les œufs et les petits pois apportent des protéines ; le riz apporte de l’énergie.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
