insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'riz-saute-oeufs-petits-pois' and owner_id is null), 1, 'La veille (ou quelques heures avant), faites cuire le riz 12 minutes dans l’eau bouillante, égouttez-le, étalez-le pour qu’il refroidisse vite et placez-le au réfrigérateur.') on conflict do nothing;
