insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('puree-lisse-carotte', 'Purée lisse de carotte', 'Un premier légume, doux et très lisse.', array['baby']::text[], array['lunch']::text[], array['start','m6_8']::text[], 4, 9, array['smooth']::text[], 6, 'portions d’environ 2 à 4 cuillères à café au début', 10, 15, array[]::text[], array['puree','vegetables','budget','freezer','batch']::text[], array['Ajoutez une noisette de beurre ou une cuillère à café d’huile de colza, selon les conseils de votre professionnel.','Plus tard, mélangez avec de la pomme de terre pour une purée plus épaisse.']::text[], 'Réfrigérateur : 48 h dans un pot fermé. Congélateur : 1 mois en portions (bacs à glaçons) ; décongeler au réfrigérateur, réchauffer une seule fois et vérifier la température.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.']::text[], 'La carotte fait découvrir un goût doux ; la diversification sert d’abord à découvrir des saveurs et des textures, le lait reste l’aliment principal.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
