insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('puree-poisson-brocoli-pdt', 'Purée de poisson blanc, brocoli et pomme de terre', 'Un premier poisson, sans arêtes.', array['baby']::text[], array['lunch']::text[], array['m6_8','m9_12']::text[], 6, 12, array['smooth','mashed']::text[], 4, 'portions bébé', 10, 15, array['fish','milk']::text[], array['complete','puree','protein','freezer']::text[], array['Sans lait : remplacez le beurre par 2 cuillères à café d’huile de colza.']::text[], 'Réfrigérateur : 48 h dans un pot fermé. Congélateur : 1 mois en portions (bacs à glaçons) ; décongeler au réfrigérateur, réchauffer une seule fois et vérifier la température.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.','Nouvel allergène : si votre enfant a déjà réagi à un aliment, a un eczéma important ou une allergie connue, ou s’il y a des allergies dans la famille, demandez d’abord l’avis de votre médecin ou de la PMI. L’application ne diagnostique pas les allergies.','Vérifiez l’absence d’arêtes.']::text[], 'Le poisson apporte des protéines ; le brocoli apporte des fibres et de la vitamine C.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
