insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('boeuf-carottes-petites-pates', 'Bœuf, carottes écrasées et petites pâtes', 'Un repas complet à mâchouiller.', array['baby']::text[], array['lunch']::text[], array['m9_12']::text[], 9, 12, array['mashed','ground']::text[], 3, 'portions bébé', 10, 20, array['gluten']::text[], array['complete','protein','iron','freezer']::text[], array['Moulinez plus finement si votre bébé n’accepte pas encore les petits morceaux.']::text[], 'Réfrigérateur : 48 h dans un pot fermé. Congélateur : 1 mois en portions (bacs à glaçons) ; décongeler au réfrigérateur, réchauffer une seule fois et vérifier la température.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.','Viande cuite à cœur, hachée finement.']::text[], 'Le bœuf apporte du fer et des protéines ; les pâtes apportent de l’énergie.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
