insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('omelette-roulee-bebe', 'Omelette roulée bien cuite en lamelles', 'À manger avec les doigts, quand bébé sait attraper.', array['baby']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18']::text[], 9, 18, array['pieces']::text[], 2, 'portions bébé', 5, 6, array['eggs','milk']::text[], array['finger','quick','protein']::text[], array['Si votre bébé ne mange pas encore avec les doigts : écrasez l’omelette dans sa purée.']::text[], 'À manger aussitôt ; restes : 24 h au réfrigérateur.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.','Nouvel allergène : si votre enfant a déjà réagi à un aliment, a un eczéma important ou une allergie connue, ou s’il y a des allergies dans la famille, demandez d’abord l’avis de votre médecin ou de la PMI. L’application ne diagnostique pas les allergies.','Toujours assis, sous la surveillance d’un adulte, pendant tout le repas.','Œuf bien cuit, jamais baveux.']::text[], 'L’œuf apporte des protéines ; manger avec les doigts aide à découvrir les textures.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
