insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('galettes-courgette-bebe', 'Petites galettes de courgette', 'Moelleuses, à manger avec les doigts.', array['baby','child']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18']::text[], 9, 48, array['pieces']::text[], 8, 'petites galettes', 15, 15, array['eggs','gluten','milk']::text[], array['finger','vegetables','freezer','family']::text[], array['Pour le reste de la famille : ajoutez des herbes et servez avec une salade.']::text[], '48 h au réfrigérateur ; 1 mois au congélateur.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.','Nouvel allergène : si votre enfant a déjà réagi à un aliment, a un eczéma important ou une allergie connue, ou s’il y a des allergies dans la famille, demandez d’abord l’avis de votre médecin ou de la PMI. L’application ne diagnostique pas les allergies.','Toujours assis, sous la surveillance d’un adulte, pendant tout le repas.','L’emmental est un fromage à pâte pressée cuite : il peut être proposé même s’il est au lait cru (repère des autorités sanitaires).']::text[], 'La courgette apporte des fibres ; l’œuf apporte des protéines.', 1, array['summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
